insert into public.grammar_golden_tests(code,test_type,sentence,is_grammatical,status,test_layer,target_phase,input_fixture,expected_language_graph)
select 'representative_rule_suite_v1.'||lpad(s.ordinal::text,2,'0')||'.'||s.candidate_code,'boundary','',true,'implemented','runtime_component',null,jsonb_build_object('suite_code',s.suite_code,'ordinal',s.ordinal,'candidate_id',s.candidate_id,'candidate_code',s.candidate_code),jsonb_build_object('expected_current_state',s.expected_current_state,'chapter',s.chapter,'capability_family',s.capability_family)
from public.grammar_representative_rule_suite_v1 s
where s.suite_code='representative-rule-suite-v1' and not exists(select 1 from public.grammar_golden_tests g where g.code='representative_rule_suite_v1.'||lpad(s.ordinal::text,2,'0')||'.'||s.candidate_code);
insert into public.grammar_golden_tests(code,test_type,sentence,is_grammatical,status,test_layer,target_phase,input_fixture,expected_language_graph)
select v.code,'boundary','',true,'implemented','runtime_component',null,'{}'::jsonb,v.expected from (values
('representative_rule_suite_v1.invariant.sample_20',jsonb_build_object('sample_size',20)),('representative_rule_suite_v1.invariant.chapters_13',jsonb_build_object('chapters_covered',13)),('representative_rule_suite_v1.invariant.all_source_verified',jsonb_build_object('source_verified_count',20)),('representative_rule_suite_v1.invariant.compiled_candidates_8',jsonb_build_object('candidates_with_compiled_rules',8)),('representative_rule_suite_v1.invariant.closed_execution_4',jsonb_build_object('compiled_execution_plane_closed_count',4)),('representative_rule_suite_v1.invariant.unclosed_compiled_4',jsonb_build_object('compiled_but_execution_plane_not_closed_count',4)),('representative_rule_suite_v1.invariant.compiler_absent',jsonb_build_object('compiler_function_count',0,'compiler_automation_present',false)),('representative_rule_suite_v1.invariant.bulk_not_ready',jsonb_build_object('representative_suite_ready_for_bulk_activation',false))) v(code,expected)
where not exists(select 1 from public.grammar_golden_tests g where g.code=v.code);
